window.kbPageData["views/entry/k-fce6cdec9af3d2a9"] = {"key":"entry/k-fce6cdec9af3d2a9","state":{"route":"entry/k-fce6cdec9af3d2a9"},"node":{"id":"k-fce6cdec9af3d2a9","mode":"k","title":"西部陆海新通道","type":"概念与词义","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["open","regional"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["经济"],"来源主题":["产业、科技与对外开放"],"资料类别":["非时政"]},"directorySummary":"4.西部陆海新通道\n西部陆海新通道位于中国西部地区腹地，北接丝绸之路经济带，南连 21 世纪海上丝绸\n之路，协同衔接长江经济带，在区域协调发展格局中具有重要战略地位。该通道利用铁路、\n公路、水运、航空等多种运输方式，由重庆向南经贵州等省份，通过广西北部湾等沿海沿边\n口岸，通达新加坡及东盟主要物流节点…","sources":[{"id":"e9d0d7601968f8ce","label":"西部陆海新通道","topic":"产业、科技与对外开放","category":"非时政","text":"4.西部陆海新通道\n西部陆海新通道位于中国西部地区腹地，北接丝绸之路经济带，南连 21 世纪海上丝绸\n之路，协同衔接长江经济带，在区域协调发展格局中具有重要战略地位。该通道利用铁路、\n公路、水运、航空等多种运输方式，由重庆向南经贵州等省份，通过广西北部湾等沿海沿边\n口岸，通达新加坡及东盟主要物流节点，运行时间比经东部地区出海节约 10 天左右。向北\n与中欧班列连接，利用兰渝铁路及西北地区主要物流节点，通达中亚、南亚、欧洲等区域。\n“陆海新通道”已与中欧班列和长江黄金水道实现联通，并已初步实现丝绸之路经济带和\n21 世纪海上丝绸之路的有机衔接。","source":{"doc":"6cbfb01fe723bba64b75","first":33,"last":33,"page":33,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"open","title":"高水平开放与经贸规则"},{"slug":"regional","title":"区域协调与城乡融合"}],"units":{"k-fce6cdec9af3d2a9":[]}};
